"""Interactive comparison of independently tested Base detail passes."""
import json,sys,html
from pathlib import Path


def main():
    out=Path(sys.argv[1]).resolve();r=json.loads((out/'summary.json').read_bytes());v=json.loads((out/'validation.json').read_bytes())
    names={'native-detail-lod':'Crossbar / housing LOD','small-hardware-lod':'Small hardware LOD','smooth-bores':'Bore smoothing','combined':'Combined candidate'}
    scopes={'whole':('Whole Base','e15-a60'),'rear':('Reverse view','e15-a180'),'top':('Top view','top'),'crossbar':('Crossbar close-up','unit-4268930'),'housing':('Lower housing close-up','unit-4527988'),'hardware':('Hardware close-up · enlarged','unit-4617749')}
    panels=[]
    for stage in names:
        for scope,(label,suffix) in scopes.items():
            before=out/(suffix+'-baseline.png' if suffix.startswith('unit-') else 'baseline-'+suffix+'.png');after=out/(suffix+'-'+stage+'.png' if suffix.startswith('unit-') else stage+'-'+suffix+'.png')
            panels.append(f'<section class="comparison" data-stage="{stage}" data-scope="{scope}" '+('' if stage=='combined' and scope=='whole' else 'hidden')+f'><div class="pair"><figure><figcaption>Original source</figcaption><img src="{html.escape(str(before))}" alt="Original {label}"></figure><figure><figcaption>{names[stage]}</figcaption><img src="{html.escape(str(after))}" alt="Candidate {label}"></figure></div></section>')
    options=''.join(f'<option value="{key}" '+('selected' if key=='combined' else '')+f'>{label}</option>' for key,label in names.items());scope_options=''.join(f'<option value="{key}">{label}</option>' for key,(label,_) in scopes.items())
    rows=[]
    for key,label in [('baseline','Original'),('enclosed-voids','Closed-cavity removal'),('hidden-units','Contained-component removal')]+list(names.items()):
        n=r['stages'][key]['definition_triangles'];saving=(r['baseline_triangles']-n)/r['baseline_triangles']*100;comment='No accepted change' if key in ('enclosed-voids','hidden-units') else ('—' if key=='baseline' else f'{saving:.1f}% less')
        rows.append(f'<tr><td>{label}</td><td>{n:,}</td><td>{comment}</td></tr>')
    compact={stage:{'triangles':r['stages'][stage]['definition_triangles'],'protected':r['stages'][stage]['byte_exact_retained_original_units'],**{k:value for k,value in v['render_comparisons'][stage].items() if k!='views'}} for stage in names}
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{margin:14px 0 8px;font-size:17px}p{margin:8px 0}.note{font-size:12px;color:var(--muted-foreground,#667085)}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats b{font-size:23px;display:block}nav{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}select,button{font:inherit;padding:7px;background:var(--background,white);color:inherit;border:1px solid var(--border,#aaa);border-radius:6px;cursor:pointer;max-width:100%}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0}figcaption{font-size:12px;margin:6px 0}img{display:block;width:100%;border-radius:var(--radius,6px)}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td{padding:5px 0;border-bottom:1px solid var(--border,#ddd)}td:nth-child(2),td:nth-child(3){text-align:right}td:nth-child(2){padding-right:14px}body[data-mode=before] figure:nth-child(2),body[data-mode=after] figure:first-child{display:none}body[data-mode=before] .pair,body[data-mode=after] .pair{grid-template-columns:1fr}[hidden]{display:none!important}@media(max-width:440px){.pair{grid-template-columns:1fr}table{font-size:12px}}
</style></head><body><h3>Base detail-pass candidates</h3><div class="stats"><div><b>709,354 → 476,924</b>triangles per Base</div><div><b>32.8%</b>combined reduction</div><div><b>464,860</b>fewer triangles across both Bases</div></div><p class="note">Source-derived inspection candidates. Original CAD and runtime assets remain unchanged. Armor/module fronts, tall covers and light bars retain their original triangle data.</p><nav><select id="stage" aria-label="Pass" onchange="update()">'''+options+'''</select><select id="scope" aria-label="View" onchange="update()">'''+scope_options+'''</select></nav><nav><button onclick="document.body.dataset.mode='both'">Both</button><button onclick="document.body.dataset.mode='before'">Original</button><button onclick="document.body.dataset.mode='after'">Candidate</button></nav>'''+''.join(panels)+'''<p id="metrics" class="note"></p><h3>Independent pass results</h3><table>'''+''.join(rows)+'''</table><p class="note">Standalone savings overlap. The combined pass plugs 422 complete ≤3 mm-radius bores and remeshes the two large units plus 292 small analytic hardware units.</p><p><b>Internal removal:</b> no whole component passed strict native material containment. The crossbar’s invalid native outer shell rejects closed-cavity removal. No geometry was deleted using the earlier visibility sampling.</p><p class="note">Bore plugs are constructive native unions with flush planar ends and 0.00001 mm radial overlap. They intentionally close selected small holes and add about 14 cm³. Native input surfaces remain unchanged during LOD. Support samples stay below 0.100 mm on the two large-unit meshes; this is not a continuous whole-model error certificate.</p><p class="note">Validation: 282 tests passed (one optional skip), byte-exact checks on every unselected unit, and 18 fixed-framing source-pose view comparisons per candidate. All candidates pass the declared render guards. Moving-pose and runtime collision promotion remain separate.</p><script>const M=__METRICS__;function update(){const s=document.getElementById('stage').value,v=document.getElementById('scope').value;document.querySelectorAll('.comparison').forEach(p=>p.hidden=p.dataset.stage!==s||p.dataset.scope!==v);const m=M[s];document.getElementById('metrics').textContent=m.triangles.toLocaleString()+' triangles per Base · '+m.protected+' unselected units checked byte for byte · worst RGB pixel change '+(m.max_changed_pixels_over_10_fraction*100).toFixed(4)+'% · worst foreground-mask change '+(m.max_foreground_mask_difference_fraction*100).toFixed(4)+'% across 18 views.';}update();console.assert(document.querySelectorAll('.comparison').length===24);console.log('Four pass candidates × six matched views; all metrics loaded.');</script></body></html>'''
    (out/'review.html').write_text(page.replace('__METRICS__',json.dumps(compact,separators=(',',':'))));print(out/'review.html')
if __name__=='__main__':main()
